"""If the full generating tuple is algebraically dependent, then the final generator is algebraic over the algebra generated by the preceding generators."""

import json
from itertools import product

RECORD_ID = "proofwiki_8791__codex_expansion"
OUTCOME = "WITNESS_FOUND"
WITNESS_DESCRIPTION = (
    "In the Q-algebra Q[t], with t a formal indeterminate, take m=1, "
    "y1=0, and y2=t."
)
REFUTATION_EXPLANATION = (
    "The nonzero polynomial X1 in Q[X1,X2] vanishes at (0,t), so the full "
    "tuple is algebraically dependent. The algebra generated by y1 over Q "
    "is Q[y1]=Q. However, t is not algebraic over Q: for every nonzero p(Z) "
    "in Q[Z], p(t) is the same nonzero formal polynomial in Q[t]. Thus the "
    "final generator is not algebraic over the algebra generated by the "
    "preceding generator."
)
SEARCH_SPACE = (
    "All 81 ordered pairs (y1,y2) in Q[t]^2 where each yi=ai+bi*t and ai,bi "
    "are drawn from the fixed ordered set (0,1,-1). The program visits every "
    "pair in fixed nested-product order and exactly certifies pairs with y1 "
    "constant and y2 nonconstant linear; the first certified witness is (0,t)."
)

# A pair (a, b) represents the formal polynomial a + b*t in Q[t].
coefficient_order = (0, 1, -1)
elements = tuple(product(coefficient_order, repeat=2))
first_witness = None
visited = 0

for y1 in elements:
    for y2 in elements:
        visited += 1
        # If y1=a is constant, X1-a is a nonzero relation for (y1,y2),
        # while Q[y1]=Q. If y2=c+d*t with d nonzero, substitution into any
        # nonzero polynomial over Q remains nonzero because t is formal.
        certified = y1[1] == 0 and y2[1] != 0
        if certified and first_witness is None:
            first_witness = (y1, y2)

assert visited == 81
assert first_witness == ((0, 0), (0, 1))

result = {
    "record_id": RECORD_ID,
    "outcome": OUTCOME,
    "witness_description": WITNESS_DESCRIPTION,
    "refutation_explanation": REFUTATION_EXPLANATION,
    "search_space": SEARCH_SPACE,
}
print(json.dumps(result, separators=(",", ":")))
